-- =====================================================================
--  스파르타 물류 - 테스트 데이터셋 (전체 초기화 + 재적재)
--  실행: docker exec -i <postgres 컨테이너> psql -U <superuser> -d <db> < seed.sql
--
--  * init.sql과 동일하게 \getenv로 스키마명을 읽어옵니다 (psql 전용 스크립트).
--    환경변수가 없으면 아래 기본값을 사용합니다.
--  * 각 서비스 스키마의 "모든 테이블"을 TRUNCATE 한 뒤 고정 UUID로 다시 적재합니다.
--  * 테이블은 서비스(JPA)가 이미 생성해 둔 상태여야 합니다.
--  * 전체가 하나의 트랜잭션이라 중간에 실패하면 전부 롤백됩니다.
--
--  [고정 UUID 규칙]
--    MASTER 유저           11111111-1111-1111-1111-111111111111 (허브 데이터 created_by와 동일)
--    배송담당자(허브별)     10000000-0000-0000-0000-0000000000NN  (NN=01~17, login: dlv01~dlv17)
--    업체 관리자            10000000-0000-0000-0000-0000000001NN  (login: comp01~comp11)
--    기타 유저              10000000-0000-0000-0000-0000000002NN
--    업체                  20000000-...-0000000000NN
--    업체 상품             30000000-...  /  허브 재고 40000000-...
--    주문 50000000-...  /  주문상품 51000000-...
--    배송 60000000-...  /  배송경로 61000000-...
--    모든 유저 비밀번호: Password1!
--
--  [Enum 값 - 코드와 다르면 치환 필요]
--    p_users.role               : MASTER, USER
--    p_users.affiliation_type   : HUB, COMPANY
--    p_users.affiliation_status : PENDING, CONFIRMED
--    p_orders.status            : CONFIRMED, CANCELLED          (CANCELLED는 추정)
--    p_deliveries.status        : DeliveryStatus 확정값
--                                 WAITING, HUB_IN_TRANSIT, HUB_ARRIVED, COMPANY_IN_TRANSIT, DELIVERED, CANCELLED
--    p_delivery_routes.status   : DeliveryRouteStatus 확정값
--                                 WAITING, IN_TRANSIT, ARRIVED, CANCELLED
--    p_delivery_routes.type     : HUB_TO_HUB, HUB_TO_COMPANY      (추정)
-- =====================================================================

\set ON_ERROR_STOP on

\getenv user_schema     DB_USER_SCHEMA
\getenv hub_schema      DB_HUB_SCHEMA
\getenv company_schema  DB_COMPANY_SCHEMA
\getenv order_schema    DB_ORDER_SCHEMA
\getenv delivery_schema DB_DELIVERY_SCHEMA

\if :{?user_schema}
\else
  \set user_schema user_schema
\endif
\if :{?hub_schema}
\else
  \set hub_schema hub_schema
\endif
\if :{?company_schema}
\else
  \set company_schema company_schema
\endif
\if :{?order_schema}
\else
  \set order_schema order_schema
\endif
\if :{?delivery_schema}
\else
  \set delivery_schema delivery_schema
\endif

\echo '[seed] schemas:' :user_schema :hub_schema :company_schema :order_schema :delivery_schema

BEGIN;

-- ---------------------------------------------------------------------
-- 1) 기존 데이터 전부 삭제 (각 서비스 스키마의 모든 테이블)
-- ---------------------------------------------------------------------
SELECT format('TRUNCATE TABLE %I.%I CASCADE', schemaname, tablename)
FROM pg_tables
WHERE schemaname IN (:'user_schema', :'hub_schema', :'company_schema', :'order_schema', :'delivery_schema')
\gexec

-- ---------------------------------------------------------------------
-- 2) 데이터 적재
-- ---------------------------------------------------------------------

-- p_users (31 rows)

-- p_hubs (17 rows)

-- p_hub_routes (272 rows)

-- p_companies (11 rows)

-- p_company_items (20 rows)

-- p_hub_items (20 rows)

-- p_orders (8 rows)

-- p_order_items (8 rows)

-- p_deliveries (8 rows)

-- p_delivery_routes (15 rows)

COMMIT;

\echo '[seed] 완료'